from __future__ import annotations

import datetime as dt
import glob
import hashlib
import json
import os
import re
import sys

VAULT = ""   # generated: set by configure(vault_root)
WINDOWS = ["10:00", "15:00", "18:00"]          # 시간대 시작 — 각 시간대는 시작부터 60분(끝 시각 포함, 10분 단위 7개)
DAY_MAX = 3
SINCE = 161                                     # 이 편부터 fix 대상(160편까지는 10-23에 예약표로 맞췄다)


def choices(w: int) -> list[str]:
    h, m = map(int, WINDOWS[w].split(":"))
    return [f"{(h * 60 + m + k) // 60:02d}:{(h * 60 + m + k) % 60:02d}" for k in range(0, 61, 10)]


def window_of(hm: str) -> int:
    """'HH:MM' → 시간대(0 아침 · 1 점심 · 2 저녁). 옛 시간대(10:30~12:00 · 15:00~16:30 · 18:30~20:00)도 같은 칸으로 본다."""
    h = int(hm[:2])
    return 0 if h < 13 else 1 if h < 17 else 2


def pick(name: str, date: str, w: int) -> str:
    """같은 파일·날짜·시간대면 늘 같은 분. 이름은 경로 없이 파일 이름."""
    c = choices(w)
    return c[int(hashlib.md5(f"{os.path.basename(name)}|{date}|{w}".encode()).hexdigest(), 16) % len(c)]


def fm(text: str) -> dict:
    m = re.match(r"---\n(.*?)\n---", text, re.S)
    out = {}
    for line in (m.group(1).splitlines() if m else []):
        k = re.match(r"([A-Za-z_]+):\s*(.*)$", line)
        if k:
            out[k.group(1)] = re.sub(r"\s+#.*$", "", k.group(2)).strip().strip('"')
    return out


def drafts(vault: str) -> list[tuple[str, dict]]:
    files = glob.glob(os.path.join(vault, "content/naver/*.md")) + glob.glob(os.path.join(vault, "content/naver/제휴/*.md"))
    return [(f, fm(open(f, encoding="utf-8").read())) for f in sorted(files)]


def episode(path: str) -> int | None:
    m = re.match(r"0*(\d+)편-", os.path.basename(path))
    return int(m.group(1)) if m else None




def when(v: str) -> tuple[str, str | None] | None:
    m = re.match(r"(\d{4}-\d{2}-\d{2})(?:\s+(\d{2}:\d{2}))?", v or "")
    return (m.group(1), m.group(2)) if m else None


def next_slot(vault: str, file: str) -> str:
    """새 원고 한 편의 'YYYY-MM-DD HH:MM'. 이 파일 자신은 세지 않는다."""
    me = os.path.basename(file)
    days: dict[str, set[int]] = {}
    for f, d in drafts(vault):
        if os.path.basename(f) == me or d.get("status") != "draft":
            continue
        w = when(d.get("scheduled", ""))
        if w:
            days.setdefault(w[0], set()).add(window_of(w[1]) if w[1] else -1)
    if not days:
        raise SystemExit("draft 원고에 scheduled 날짜가 하나도 없다 — 시작 날짜를 손으로 정한다")
    last = max(days)
    used = days[last]
    date = last
    if len(used) >= DAY_MAX or -1 in used:   # 시각 없는 날은 꽉 찬 것으로 본다(모르면 막는 쪽)
        date = (dt.date.fromisoformat(last) + dt.timedelta(days=1)).isoformat()
        used = set()
    w = min(set(range(len(WINDOWS))) - used)
    return f"{date} {pick(me, date, w)}"




def clashes(vault: str) -> list[str]:
    """같은 날 같은 시간대에 두 편, 또는 하루 DAY_MAX편 넘게 잡힌 draft·hold. 10-25 수동 실행: hold 166편(11-07 10:10)과
    draft 167편(11-07 10:20)이 같은 아침 칸이었다 — next는 hold를 세지 않는다. hold를 draft로 돌릴 때 next로 자리를 다시 받는다."""
    seen: dict[str, list[tuple[int, str]]] = {}
    for f, d in drafts(vault):
        if d.get("status") not in ("draft", "hold"):
            continue
        w = when(d.get("scheduled", ""))
        if w and w[1]:
            seen.setdefault(w[0], []).append((window_of(w[1]), f"{os.path.basename(f)[:-3]}({d['status']} {w[1]})"))
    out = []
    for day, rows in sorted(seen.items()):
        by = {}
        for win, name in rows:
            by.setdefault(win, []).append(name)
        out += [f"{day} {['아침', '점심', '저녁'][win]} 칸에 {len(ns)}편: {', '.join(ns)}" for win, ns in sorted(by.items()) if len(ns) > 1]
        if len(rows) > DAY_MAX:
            out.append(f"{day} 하루 {len(rows)}편(상한 {DAY_MAX}): {', '.join(n for _, n in rows)}")
    return out


